import { useCallback, useEffect, useMemo, useState } from 'react'
import {
  createCategory,
  deleteCategory,
  getCategories,
  updateCategory,
} from '../../../services/reportService'
import SelectionBar from '../../../components/common/SelectionBar'
import Pagination from '../../../components/common/Pagination'
import { swalSuccess, swalError, swalConfirm, swalConfirmDelete, swalLoading, swalClose } from '../../../utils/swal'
import { parseApiError } from '../../../utils/apiError'

const DEFAULT_FORM = {
  id: null,
  name: '',
  icon: 'category',
  color: '#206223',
  isActive: true,
}

const PAGE_SIZE = 6

const ICON_OPTIONS = [
  'recycling', 'warning', 'architecture', 'delete',
  'water_drop', 'eco', 'construction', 'streetview',
  'lightbulb', 'local_fire_department', 'pest_control', 'category',
]

const COLOR_OPTIONS = [
  '#206223', '#00639a', '#ba1a1a',
  '#6b4f45', '#FF9800', '#7B1FA2',
]

export default function CategoryManager() {
  const [categories, setCategories] = useState([])
  const [loading, setLoading] = useState(false)
  const [submitting, setSubmitting] = useState(false)
  const [error, setError] = useState('')
  const [search, setSearch] = useState('')
  const [form, setForm] = useState(DEFAULT_FORM)
  const [showModal, setShowModal] = useState(false)
  const [page, setPage] = useState(1)
  const [selectedIds, setSelectedIds] = useState([])

  const loadCategories = useCallback(async () => {
    setLoading(true)
    setError('')
    try {
      const res = await getCategories()
      setCategories(Array.isArray(res.data) ? res.data : [])
    } catch (err) {
      setError(parseApiError(err, 'Không thể tải danh mục'))
    } finally {
      setLoading(false)
    }
  }, [])

  useEffect(() => {
    loadCategories()
  }, [loadCategories])

  const filteredCategories = useMemo(() => {
    const keyword = search.trim().toLowerCase()
    if (!keyword) return categories
    return categories.filter((category) =>
      [category.name, category.icon, category.color]
        .filter(Boolean)
        .some((value) => String(value).toLowerCase().includes(keyword))
    )
  }, [categories, search])

  const totalPages = Math.max(1, Math.ceil(filteredCategories.length / PAGE_SIZE))
  const currentPage = Math.min(page, totalPages)
  const paginatedCategories = filteredCategories.slice(
    (currentPage - 1) * PAGE_SIZE,
    currentPage * PAGE_SIZE
  )

  const activeCount = categories.filter((c) => c.isActive).length
  const hotCategory = useMemo(() => {
    if (categories.length === 0) return '—'
    return categories[0]?.name || '—'
  }, [categories])

  const isEditing = form.id !== null

  const resetForm = () => {
    setForm(DEFAULT_FORM)
    setError('')
  }

  const openCreate = () => {
    resetForm()
    setShowModal(true)
  }

  const openEdit = (category) => {
    setForm({
      id: category.id,
      name: category.name || '',
      icon: category.icon || 'category',
      color: category.color || '#206223',
      isActive: Boolean(category.isActive ?? true),
    })
    setError('')
    setShowModal(true)
  }

  const closeModal = () => {
    setShowModal(false)
    resetForm()
  }

  const updateField = (key, value) => {
    setForm((prev) => ({ ...prev, [key]: value }))
  }

  const handleSubmit = async (event) => {
    event.preventDefault()
    setError('')

    if (!form.name.trim()) {
      setError('Vui lòng nhập tên danh mục')
      return
    }

    setSubmitting(true)
    try {
      if (isEditing) {
        await updateCategory(form.id, form)
        setCategories((prev) =>
          prev.map((c) => (c.id === form.id ? { ...c, ...form } : c))
        )
      } else {
        const res = await createCategory(form)
        const created = res?.data
        if (created) {
          setCategories((prev) => [...prev, created])
        } else {
          await loadCategories()
        }
      }
      closeModal()
      swalSuccess(isEditing ? 'Cập nhật danh mục thành công!' : 'Thêm danh mục thành công!')
    } catch (err) {
      const msg = parseApiError(err)
      if (msg) swalError(msg)
    } finally {
      setSubmitting(false)
    }
  }

  const handleToggleActive = async (category) => {
    setSubmitting(true)
    setError('')
    try {
      await updateCategory(category.id, { ...category, isActive: !category.isActive })
      setCategories((prev) =>
        prev.map((c) => (c.id === category.id ? { ...c, isActive: !category.isActive } : c))
      )
      swalSuccess('Đã cập nhật trạng thái!')
    } catch (err) {
      const msg = parseApiError(err, 'Không thể cập nhật trạng thái')
      if (msg) swalError(msg)
    } finally {
      setSubmitting(false)
    }
  }

  const handleDelete = async (category) => {
    const confirmed = await swalConfirmDelete(category.name)
    if (!confirmed) return

    setSubmitting(true)
    setError('')
    try {
      await deleteCategory(category.id)
      await loadCategories()
      swalSuccess('Đã xoá danh mục!')
    } catch (err) {
      const msg = parseApiError(err, 'Không thể xóa danh mục')
      if (msg) swalError(msg)
    } finally {
      setSubmitting(false)
    }
  }

  const toggleSelect = (id) =>
    setSelectedIds(prev => prev.includes(id) ? prev.filter(x => x !== id) : [...prev, id])

  const toggleSelectAll = () => {
    if (selectedIds.length === paginatedCategories.length) setSelectedIds([])
    else setSelectedIds(paginatedCategories.map(c => c.id))
  }

  const handleBulkDelete = async () => {
    if (!(await swalConfirm(`Xoá ${selectedIds.length} danh mục đã chọn?`, 'Hành động này không thể hoàn tác.'))) return
    swalLoading('Đang xoá...')
    let ok = 0, fail = 0
    for (const id of selectedIds) {
      try { await deleteCategory(id); ok++ } catch { fail++ }
    }
    swalClose()
    setSelectedIds([])
    await loadCategories()
    if (fail) swalError(`Xoá thất bại ${fail}/${ok + fail} danh mục`)
    else swalSuccess(`Đã xoá ${ok} danh mục!`)
  }

  const activePercent = categories.length > 0
    ? Math.round((activeCount / categories.length) * 100)
    : 0

  return (
    <section className="space-y-8">
      {/* Page Title & Actions */}
      <div className="flex flex-col md:flex-row md:items-end justify-between gap-6">
        <div className="space-y-2">
          <h1 className="text-4xl font-extrabold text-on-surface tracking-tight font-headline">
            Quản lý Danh mục
          </h1>
        </div>
        <div className="flex items-center gap-3">
          <div className="bg-surface-container-low rounded-xl px-4 py-2 flex items-center gap-2 border border-outline-variant/10 shadow-sm focus-within:ring-2 ring-primary/20 transition-all">
            <span className="material-symbols-outlined text-on-surface-variant text-xl">search</span>
            <input
              value={search}
              onChange={(e) => { setSearch(e.target.value); setPage(1) }}
              className="bg-transparent border-none focus:ring-0 text-sm w-48 lg:w-64 placeholder:text-on-surface-variant/50"
              placeholder="Tìm kiếm danh mục..."
              type="text"
            />
          </div>
          <button
            onClick={openCreate}
            className="bg-primary-fixed hover:bg-primary-fixed-dim text-on-primary-fixed px-6 py-2.5 rounded-xl font-bold flex items-center gap-2 transition-all shadow-md"
          >
            <span className="material-symbols-outlined">add_circle</span>
            Thêm danh mục mới
          </button>
        </div>
      </div>

      {/* Error Banner */}
      {error && !showModal && (
        <div className="rounded-xl bg-error-container text-on-error-container px-4 py-3 text-sm font-medium">
          {error}
        </div>
      )}

      {/* Selection Bar */}
      <SelectionBar count={selectedIds.length} onClear={() => setSelectedIds([])}>
        <button onClick={handleBulkDelete} className="flex items-center gap-1.5 px-4 py-2 rounded-xl bg-error text-on-error text-sm font-bold hover:bg-error/90 transition-colors">
          <span className="material-symbols-outlined text-lg">delete</span>
          Xoá ({selectedIds.length})
        </button>
      </SelectionBar>

      {/* Categories Data Table */}
      <div className="bg-surface rounded-3xl border border-outline-variant overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead>
              <tr className="border-b border-outline-variant bg-surface-container">
                <th className="px-3 py-4 w-10">
                  <input type="checkbox" className="accent-primary w-4 h-4 cursor-pointer" checked={paginatedCategories.length > 0 && selectedIds.length === paginatedCategories.length} onChange={toggleSelectAll} />
                </th>
                <th className="px-5 py-4 text-left font-semibold text-on-surface-variant">STT</th>
                <th className="px-5 py-4 text-left font-semibold text-on-surface-variant">Tên Danh Mục</th>
                <th className="px-5 py-4 text-left font-semibold text-on-surface-variant">Icon &amp; Màu sắc</th>
                <th className="px-5 py-4 text-center font-semibold text-on-surface-variant">Trạng thái</th>
                <th className="px-5 py-4 text-right font-semibold text-on-surface-variant">Thao tác</th>
              </tr>
            </thead>
            <tbody>
              {loading ? (
                <tr>
                  <td colSpan={6} className="px-8 py-12 text-center text-on-surface-variant">
                    Đang tải danh mục...
                  </td>
                </tr>
              ) : paginatedCategories.length === 0 ? (
                <tr>
                  <td colSpan={6} className="px-8 py-12 text-center text-on-surface-variant">
                    Chưa có danh mục phù hợp.
                  </td>
                </tr>
              ) : (
                paginatedCategories.map((category, idx) => (
                  <tr key={category.id} className={`border-b border-outline-variant/50 hover:bg-surface-container/50 transition-colors ${selectedIds.includes(category.id) ? 'bg-primary-fixed/30' : ''}`}>
                    <td className="px-3 py-4 w-10">
                      <input type="checkbox" className="accent-primary w-4 h-4 cursor-pointer" checked={selectedIds.includes(category.id)} onChange={() => toggleSelect(category.id)} />
                    </td>
                    <td className="px-5 py-4 text-xs text-on-surface-variant">
                      {(currentPage - 1) * PAGE_SIZE + idx + 1}
                    </td>
                    <td className="px-5 py-4">
                      <div className="flex flex-col">
                        <span className="text-base font-bold text-on-surface">{category.name}</span>
                        <span className="text-xs text-on-surface-variant/60">{category.icon || 'category'}</span>
                      </div>
                    </td>
                    <td className="px-5 py-4">
                      <div className="flex items-center gap-3">
                        <div
                          className="w-10 h-10 rounded-xl flex items-center justify-center shadow-sm"
                          style={{ backgroundColor: (category.color || '#206223') + '15' }}
                        >
                          <span
                            className="material-symbols-outlined"
                            style={{ color: category.color || '#206223' }}
                          >
                            {category.icon || 'category'}
                          </span>
                        </div>
                        <span className="text-xs font-mono font-medium text-on-surface-variant bg-surface-container-low px-2 py-1 rounded">
                          {category.color || '#206223'}
                        </span>
                      </div>
                    </td>
                    <td className="px-5 py-4 text-center">
                      {category.isActive ? (
                        <span className="inline-flex items-center px-3 py-1 rounded-full text-xs font-bold bg-primary-fixed text-on-primary-fixed">
                          <span className="w-1.5 h-1.5 rounded-full bg-primary mr-2" />
                          Hoạt động
                        </span>
                      ) : (
                        <span className="inline-flex items-center px-3 py-1 rounded-full text-xs font-bold bg-surface-container text-on-surface-variant">
                          <span className="w-1.5 h-1.5 rounded-full bg-outline mr-2" />
                          Vô hiệu
                        </span>
                      )}
                    </td>
                    <td className="px-5 py-4 text-right">
                      <div className="flex items-center justify-end gap-1">
                        <button
                          onClick={() => openEdit(category)}
                          className="p-2 rounded-xl hover:bg-primary/10 text-primary transition-colors"
                          title="Chỉnh sửa"
                        >
                          <span className="material-symbols-outlined">edit</span>
                        </button>
                        <button
                          onClick={() => handleToggleActive(category)}
                          disabled={submitting}
                          className="p-2 rounded-xl hover:bg-error/10 text-error transition-colors disabled:opacity-50"
                          title={category.isActive ? 'Vô hiệu hóa' : 'Kích hoạt'}
                        >
                          <span className="material-symbols-outlined">
                            {category.isActive ? 'block' : 'check_circle'}
                          </span>
                        </button>
                        <button
                          onClick={() => handleDelete(category)}
                          disabled={submitting}
                          className="p-2 rounded-xl hover:bg-error/10 text-error transition-colors disabled:opacity-50"
                          title="Xóa"
                        >
                          <span className="material-symbols-outlined">delete</span>
                        </button>
                      </div>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>

        <Pagination currentPage={currentPage} totalPages={totalPages} totalRecords={filteredCategories.length} label="danh mục" onPageChange={setPage} />
      </div>

      {/* Modal */}
      {showModal && (
        <div className="modal-overlay z-[100]">
          <form
            onSubmit={handleSubmit}
            className="modal-panel w-full max-w-2xl"
          >
            {/* Modal Header */}
            <div className="p-8 pb-4">
              <div className="flex justify-between items-start">
                <div>
                  <h2 className="text-3xl font-headline font-extrabold text-primary tracking-tight">
                    {isEditing ? 'Cập nhật danh mục' : 'Thêm danh mục mới'}
                  </h2>
                  <p className="text-on-surface-variant mt-1">
                    {isEditing
                      ? 'Chỉnh sửa thông tin danh mục trong hệ thống Hanoi CleanCity.'
                      : 'Tạo một danh mục báo cáo mới cho hệ thống Hanoi CleanCity.'}
                  </p>
                </div>
                <button
                  type="button"
                  onClick={closeModal}
                  className="text-outline hover:text-on-surface transition-colors"
                >
                  <span className="material-symbols-outlined text-3xl">close</span>
                </button>
              </div>
            </div>

            {/* Modal Content (Scrollable) */}
            <div className="flex-1 overflow-y-auto custom-scrollbar p-8 pt-4 space-y-8">
              {/* Section 1: Name */}
              <div className="space-y-3">
                <label className="block text-sm font-semibold text-on-surface-variant tracking-wider uppercase">
                  Tên danh mục
                </label>
                <input
                  value={form.name}
                  onChange={(e) => updateField('name', e.target.value)}
                  className="w-full px-4 py-4 bg-surface-container-low border-none rounded-xl focus:ring-2 focus:ring-primary text-lg font-medium text-on-surface placeholder:text-outline-variant/60 transition-all"
                  placeholder="Ví dụ: Rác thải nguy hại"
                  type="text"
                />
              </div>

              {/* Section 2: Icon & Color Picker */}
              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                {/* Icon Selection */}
                <div className="space-y-3">
                  <label className="block text-sm font-semibold text-on-surface-variant tracking-wider uppercase">
                    Biểu tượng
                  </label>
                  <div className="grid grid-cols-4 gap-3 p-4 bg-surface-container-low rounded-xl">
                    {ICON_OPTIONS.map((icon) => (
                      <button
                        key={icon}
                        type="button"
                        onClick={() => updateField('icon', icon)}
                        className={`aspect-square flex items-center justify-center rounded-lg transition-all active:scale-95 ${
                          form.icon === icon
                            ? 'bg-primary text-on-primary shadow-lg'
                            : 'text-primary hover:bg-surface-variant'
                        }`}
                      >
                        <span
                          className="material-symbols-outlined"
                          style={form.icon === icon ? { fontVariationSettings: "'FILL' 1" } : undefined}
                        >
                          {icon}
                        </span>
                      </button>
                    ))}
                  </div>
                </div>

                {/* Color Swatches */}
                <div className="space-y-3">
                  <label className="block text-sm font-semibold text-on-surface-variant tracking-wider uppercase">
                    Màu sắc chủ đạo
                  </label>
                  <div className="grid grid-cols-3 gap-3 p-4 bg-surface-container-low rounded-xl h-full content-start">
                    {COLOR_OPTIONS.map((color) => (
                      <button
                        key={color}
                        type="button"
                        onClick={() => updateField('color', color)}
                        className={`h-10 rounded-full hover:scale-105 transition-transform ${
                          form.color === color
                            ? 'border-4 border-white shadow-sm ring-2 ring-primary'
                            : ''
                        }`}
                        style={{ backgroundColor: color }}
                      />
                    ))}
                  </div>
                </div>
              </div>

              {/* Section 3: Status Toggle */}
              <div className="flex items-center justify-between p-6 bg-surface-container-low rounded-xl">
                <div>
                  <span className="block font-bold text-on-surface">Trạng thái hoạt động</span>
                  <span className="text-sm text-on-surface-variant">
                    Cho phép người dân gửi báo cáo thuộc danh mục này ngay lập tức.
                  </span>
                </div>
                <label className="relative inline-flex items-center cursor-pointer">
                  <input
                    type="checkbox"
                    checked={form.isActive}
                    onChange={(e) => updateField('isActive', e.target.checked)}
                    className="sr-only peer"
                  />
                  <div className="w-14 h-8 bg-surface-variant peer-focus-visible:ring-2 peer-focus-visible:ring-primary peer-focus-visible:ring-offset-2 rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[4px] after:left-[4px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-6 after:w-6 after:transition-all peer-checked:bg-primary" />
                </label>
              </div>

              {/* Error */}
              {error && showModal && (
                <div className="rounded-xl bg-error-container text-on-error-container px-4 py-3 text-sm font-medium">
                  {error}
                </div>
              )}
            </div>

            {/* Modal Footer */}
            <div className="p-8 bg-surface-container-low border-t border-outline-variant/10 flex items-center justify-end gap-4">
              <button
                type="button"
                onClick={closeModal}
                className="px-8 py-3 text-primary font-bold hover:bg-surface-variant rounded-xl transition-colors"
              >
                Hủy
              </button>
              <button
                type="submit"
                disabled={submitting}
                className="btn-primary px-10 py-3 hover:shadow-primary/20 hover:scale-[1.02]"
              >
                {submitting ? 'Đang xử lý...' : isEditing ? 'Lưu thay đổi' : 'Lưu danh mục'}
              </button>
            </div>
          </form>
        </div>
      )}
    </section>
  )
}